<?php namespace Tests\Feature; use App\Models\{User,PrayerRecord}; use App\Services\PrayerTimeService; use Carbon\Carbon; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class PrayerTest extends TestCase { use RefreshDatabase;
 public function test_all_statuses(): void { $u=User::factory()->create(); foreach(['waqt_par','late','qaza','missed'] as $i=>$s){ PrayerRecord::create(['user_id'=>$u->id,'prayer_name'=>'Fajr','prayer_date'=>now()->addDays($i)->toDateString(),'status'=>$s]); $this->assertDatabaseHas('prayer_records',['status'=>$s]); } $this->assertCount(4,PrayerRecord::all()); }
 public function test_unmarked_is_null_not_missed(): void { $u=User::factory()->create(); $this->actingAs($u)->post('/salah/status',['prayer_name'=>'Fajr','prayer_date'=>now()->toDateString(),'status'=>''])->assertRedirect(); $this->assertEquals(0,PrayerRecord::count()); }
 public function test_hanafi_default_and_calc_returns_times(): void { $u=User::factory()->create(); $this->assertEquals('Hanafi',$u->prayerSetting->asr_juristic); $this->assertEquals(2,$u->prayerSetting->asr_shadow_factor); $svc=app(PrayerTimeService::class); $t=$svc->computeForDate($u->prayerSetting,Carbon::parse('2026-11-03')); foreach(['fajr','dhuhr','asr','maghrib','isha'] as $k){ $this->assertMatchesRegularExpression('/^\d{2}:\d{2}:00$/',$t[$k],$k); } // Asr Hanafi should be later than a Shafi (factor1) calculation for Faisalabad on this date
   $s2=$u->prayerSetting->replicate(); $s2->asr_shadow_factor=1; $s2->asr_juristic='Standard'; $t2=$svc->computeForDate($s2,Carbon::parse('2026-11-03')); $this->assertGreaterThan($t2['asr'],$t['asr']); }
}
